syntax:
std::unique_ptr<T> ptr;
std::shared_ptr<T> ptr;
std::weak_ptr<T> ptr;

code_example:
#include <iostream>
#include <memory>

class Resource {
public:
    Resource() { std::cout << "Resource acquired" << std::endl; }
    ~Resource() { std::cout << "Resource destroyed" << std::endl; }
    void doSomething() { std::cout << "Doing something with resource" << std::endl; }
};

int main() {
    {
        auto ptr = std::make_unique<Resource>();
        ptr->doSomething();
    } // ptr goes out of scope here, Resource is automatically destroyed

    std::shared_ptr<Resource> sharedPtr1 = std::make_shared<Resource>();
    {
        std::shared_ptr<Resource> sharedPtr2 = sharedPtr1;
        sharedPtr2->doSomething();
        std::cout << "Shared pointers in scope" << std::endl;
    } // sharedPtr2 goes out of scope, but Resource remains until sharedPtr1 is destroyed
    std::cout << "End of main" << std::endl;
    return 0;
}
